// ─────────────────────────────────────────────────────────────────────────────
// Build Search Request
// HubSpot CRM search body for SEARCH_SCOPE:
//   modified_since → hs_lastmodifieddate ≥ now − LOOKBACK_HOURS
//   backfill       → hs_object_id > cursor (workflow static data, or
//                    BACKFILL_START_AFTER_ID), walking the whole portal
//   unprocessed    → CLEAN_NAME_PROPERTY has no value
// Always: name has a value; sorted by hs_object_id ascending, 100 per page.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const storedCursor = store && store.backfillCursor ? String(store.backfillCursor) : null;
const cursor = storedCursor || cfg.backfillStartAfterId || '0';
const filters = [{ propertyName: 'name', operator: 'HAS_PROPERTY' }];
if (cfg.searchScope === 'modified_since') filters.push({ propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: String(Date.now() - cfg.lookbackHours * 3600000) });
if (cfg.searchScope === 'backfill') filters.push({ propertyName: 'hs_object_id', operator: 'GT', value: cursor });
if (cfg.searchScope === 'unprocessed') {
  if (!cfg.cleanNameProperty) throw new Error('SEARCH_SCOPE=unprocessed needs CLEAN_NAME_PROPERTY.');
  filters.push({ propertyName: cfg.cleanNameProperty, operator: 'NOT_HAS_PROPERTY' });
}
const properties = [...new Set(['name', 'hs_object_id', 'hs_lastmodifieddate', cfg.cleanNameProperty, cfg.rawNameProperty, cfg.matchKeyProperty].filter(Boolean))];
return [{ json: {
  searchBody: { filterGroups: [{ filters }], sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }], properties, limit: 100 },
  maxPages: Math.max(1, Math.ceil(cfg.batchLimit / 100)),
  cursor: cfg.searchScope === 'backfill' ? cursor : null,
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Collect Search Pages
// Flattens every page returned by the paginated search, caps at BATCH_LIMIT
// and notes when HubSpot's 10,000-result search ceiling is reached.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const pages = $input.all().map((i) => i.json);
if (pages.length === 1 && pages[0].error) throw new Error(`HubSpot search failed: ${JSON.stringify(pages[0].error).slice(0, 300)}`);
const seen = new Set();
const companies = [];
for (const pg of pages) for (const r of pg.results || []) {
  if (seen.has(String(r.id)) || companies.length >= cfg.batchLimit) continue;
  seen.add(String(r.id));
  companies.push({ id: String(r.id), properties: r.properties || {} });
}
const total = Number(pages[0]?.total) || companies.length;
return [{ json: { source: 'hubspot', scope: cfg.searchScope, cursor: $('Build Search Request').first().json.cursor, total, companies,
  maxId: companies.reduce((m, c) => Math.max(m, Number(c.id) || 0), 0),
  moreAvailable: total > companies.length, searchCapReached: total > 10000 } }];

// ─────────────────────────────────────────────────────────────────────────────
// Legal Suffix Normalization & Cleaning
// Rules (README §9):
//  • Whitespace is collapsed and the name trimmed; case is never changed.
//  • Suffixes are matched only at the END of the name, as whole tokens,
//    longest phrase first, repeatedly (stacked suffixes, max 5 passes).
//    "Inc." inside "Incredible Foods" can never match.
//  • Tokens are compared without dots, commas or spaces, so LLC / L.L.C. /
//    L. L. C. and "Co., Ltd." all match.
//  • Ambiguous short forms that are also ordinary words (Spa, SA, AG, PC, LP…)
//    are stripped only when written as a legal form: with dots, in capitals
//    (unless the whole name is capitals), or in their canonical mixed case.
//  • Descriptors (Holdings, Group, Company) are stripped only with
//    STRIP_DESCRIPTORS=true.
//  • A strip is refused if nothing meaningful would remain ("The Group").
//  • PROTECTED_NAMES are never modified.
// Outputs per record: cleaned_name, extracted_suffixes, was_modified, match_key.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { companies } = $input.first().json;

// Legal entity forms (compact = lowercase, no dots/commas/spaces).
const LEGAL = [
  // US
  'llc', 'inc', 'incorporated', 'corp', 'corporation', 'co', 'company?', 'llp', 'lllp', 'lp', 'pc', 'pllc', 'pa', 'ltd', 'limited', 'ltda',
  '&co', 'andco', 'coinc', 'coltd', 'colimited',
  // UK / IE / Commonwealth
  'plc', 'cic', 'ptyltd', 'ptylimited', 'pty', 'pvtltd', 'privatelimited', 'pteltd', 'sdnbhd', 'bhd', 'nl',
  // DACH / Nordics / Benelux
  'gmbh', 'gmbh&cokg', 'gmbhcokg', 'ag', 'kg', 'ohg', 'ug', 'eg', 'ev', 'se', 'kgaa',
  'bv', 'nv', 'bvba', 'vof', 'cv', 'ab', 'as', 'asa', 'aps', 'oy', 'oyj',
  // FR / ES / IT / PT / LATAM
  'sa', 'sas', 'sasu', 'sarl', 'eurl', 'sca', 'snc', 'sl', 'slu', 'srl', 'srls', 'spa', 'sapa', 'scarl', 'lda',
  'sadecv', 'sderldecv', 'srldecv', 'sapi', 'sapidecv', 'eireli', 'me', 'epp', 'saa', 'sac', 'spa',
  // CEE
  'spzoo', 'sp', 'sro', 'as', 'doo', 'kft', 'zrt', 'nyrt', 'ad', 'ood', 'eood', 'srl',
  // APAC
  'kk', 'gk', 'yk', 'cokk', 'ptyltd', 'tbk', 'pt', 'jsc', 'ojsc', 'llc',
].filter((x) => !x.endsWith('?'));
const DESCRIPTORS = ['holdings', 'holding', 'group', 'company'];
// Short forms that are also ordinary words or brand tokens.
const AMBIGUOUS = new Set(['spa', 'sa', 'as', 'ab', 'ag', 'kg', 'se', 'sl', 'oy', 'bv', 'nv', 'pc', 'lp', 'pa', 'nl', 'cv', 'ad', 'me', 'eg', 'ev', 'ug', 'pt', 'sp', 'kk', 'gk', 'yk', 'sas', 'sac', 'epp', 'doo', 'sapi']);
const CANONICAL = new Set(['SpA', 'GmbH', 'AG', 'KG', 'SE', 'SA', 'SL', 'BV', 'NV', 'AB', 'AS', 'Oy', 'PC', 'LP', 'PA', 'eG', 'e.V.', 'UG', 'PT', 'KK', 'GK', 'SAS', 'SAC', 'SL', 'S.A.', 'AD', 'NL', 'CV']);
const LEGAL_SET = new Set(LEGAL);
const DESC_SET = new Set(DESCRIPTORS);
const STOP = new Set(['the', 'and', '&', 'of', 'a', 'an', 'de', 'la', 'le', 'el', 'der', 'die', 'das', 'und', 'et', 'y']);
const MAX_PHRASE = 6;

const compact = (s) => s.toLowerCase().replace(/[.,\s]/g, '');
const lettersOf = (s) => s.replace(/[^\p{L}]/gu, '');
const protectedSet = new Set(cfg.protectedNames.map((n) => n.toLowerCase().replace(/\s+/g, ' ').trim()));

function hasCore(tokens) {
  return tokens.some((t) => { const w = t.toLowerCase().replace(/[^\p{L}\p{N}&]/gu, ''); return w.length >= 2 && !STOP.has(w); });
}

function clean(raw) {
  const original = raw == null ? '' : String(raw);
  const collapsed = original.replace(/[ \s]+/g, ' ').trim();
  if (!collapsed) return { cleaned: '', suffixes: [], modified: false, status: 'no_name' };
  if (protectedSet.has(collapsed.toLowerCase())) return { cleaned: collapsed, suffixes: [], modified: false, status: 'protected_name' };
  const nameIsAllCaps = lettersOf(collapsed).length > 0 && lettersOf(collapsed) === lettersOf(collapsed).toUpperCase();

  let tokens = collapsed.split(' ');
  const extracted = [];
  const refused = [];
  for (let pass = 0; pass < 5 && tokens.length > 1; pass += 1) {
    let hit = null;
    for (let L = Math.min(MAX_PHRASE, tokens.length - 1); L >= 1 && !hit; L -= 1) {
      const tail = tokens.slice(tokens.length - L);
      // A leading comma on the tail ("Solutions, LLC") belongs to the previous token.
      const tailText = tail.join(' ').replace(/^[,;]+/, '');
      const key = compact(tailText);
      const isLegal = LEGAL_SET.has(key);
      const isDesc = cfg.stripDescriptors && DESC_SET.has(key);
      if (!isLegal && !isDesc) continue;
      if (AMBIGUOUS.has(key)) {
        const bare = tailText.replace(/[,;]+$/, '');
        const dotted = /\./.test(bare);
        const caps = lettersOf(bare) === lettersOf(bare).toUpperCase() && !nameIsAllCaps;
        if (!dotted && !caps && !CANONICAL.has(bare)) { refused.push({ suffix: bare, reason: 'ambiguous_form' }); continue; }
      }
      const rest = tokens.slice(0, tokens.length - L);
      if (!hasCore(rest)) { refused.push({ suffix: tailText, reason: 'would_leave_no_core_name' }); continue; }
      hit = { L, text: tailText.replace(/[,;]+$/, ''), kind: isLegal ? 'legal' : 'descriptor' };
    }
    if (!hit) break;
    extracted.unshift(hit.text);
    tokens = tokens.slice(0, tokens.length - hit.L);
    // Trailing punctuation / connectors left behind ("Solutions," / "Harbor &").
    while (tokens.length > 1 && /^(&|and|und|et|y|-|–|—)$/i.test(tokens[tokens.length - 1])) tokens.pop();
    tokens[tokens.length - 1] = tokens[tokens.length - 1].replace(/[,;:\-–—/]+$/, '');
    if (!tokens[tokens.length - 1]) tokens.pop();
  }
  let cleaned = tokens.join(' ').replace(/\s+([,;:])/g, '$1').replace(/[,;:\-–—/\s]+$/, '').trim();
  // Unbalanced trailing "(" left by "Acme (UK Ltd)" style input.
  if ((cleaned.match(/\(/g) || []).length > (cleaned.match(/\)/g) || []).length) cleaned = cleaned.replace(/\s*\([^)]*$/, '').trim();
  if (cleaned.length < cfg.minCleanLength) return { cleaned: collapsed, suffixes: [], modified: collapsed !== original, status: 'too_short_after_clean', refused };
  return { cleaned, suffixes: extracted, modified: cleaned !== original, status: extracted.length ? 'suffix_removed' : cleaned !== original ? 'whitespace_normalized' : 'already_clean', refused };
}

function matchKey(name) {
  let s = String(name || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase();
  s = s.replace(/ł/g, 'l').replace(/ø/g, 'o').replace(/ß/g, 'ss').replace(/æ/g, 'ae').replace(/œ/g, 'oe').replace(/đ/g, 'd');
  s = s.replace(/&/g, ' and ').replace(/\+/g, ' and ');
  if (cfg.matchKeyDropLeadingThe) s = s.replace(/^\s*the\s+/, '');
  return s.replace(/[^\p{L}\p{N}]/gu, '');
}

const records = companies.map((c) => {
  const p = c.properties || {};
  const raw = p.name;
  const r = clean(raw);
  const key = r.cleaned ? matchKey(r.cleaned) : '';
  return {
    id: String(c.id),
    original_name: raw == null ? null : String(raw),
    cleaned_name: r.cleaned,
    extracted_suffixes: r.suffixes,
    was_modified: r.modified,
    match_key: key,
    status: r.status,
    refused: r.refused || [],
    current: { clean: p[cfg.cleanNameProperty] ?? null, raw: cfg.rawNameProperty ? (p[cfg.rawNameProperty] ?? null) : null, matchKey: cfg.matchKeyProperty ? (p[cfg.matchKeyProperty] ?? null) : null },
  };
});
const counts = { scanned: records.length, modified: records.filter((r) => r.was_modified).length, suffix_removed: records.filter((r) => r.status === 'suffix_removed').length, whitespace_normalized: records.filter((r) => r.status === 'whitespace_normalized').length, already_clean: records.filter((r) => r.status === 'already_clean').length, protected: records.filter((r) => r.status === 'protected_name').length, no_name: records.filter((r) => r.status === 'no_name').length, too_short: records.filter((r) => r.status === 'too_short_after_clean').length };
return [{ json: { counts, records } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Batch Updates
// Decides per record what (if anything) to write, then chunks the writes into
// HubSpot batch/update requests of UPDATE_BATCH_SIZE (≤ 100).
//   preserve (default): CLEAN_NAME_PROPERTY ← cleaned_name; `name` untouched
//   overwrite (OVERWRITE_NAME=true): name ← cleaned_name, original copied to
//     RAW_NAME_PROPERTY first (only if that property is still empty)
//   MATCH_KEY_PROPERTY ← match_key, when configured
// Only modified records are written unless WRITE_UNCHANGED=true. Values that
// already match HubSpot are skipped. Guards: overwrite without a backup
// property, the change-ratio circuit breaker and MAX_UPDATES_PER_RUN.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { records, counts } = $input.first().json;
const SKIP_STATUS = new Set(['no_name', 'protected_name', 'too_short_after_clean']);

const updates = [];
const skipped = [];
for (const r of records) {
  if (SKIP_STATUS.has(r.status)) { skipped.push({ id: r.id, reason: r.status }); continue; }
  if (!r.was_modified && !cfg.writeUnchanged) { skipped.push({ id: r.id, reason: 'unchanged' }); continue; }
  const props = {};
  if (cfg.overwriteName) {
    if (r.was_modified) {
      props.name = r.cleaned_name;
      if (cfg.rawNameProperty && !r.current.raw) props[cfg.rawNameProperty] = r.original_name;
    }
    if (cfg.cleanNameProperty && r.current.clean !== r.cleaned_name) props[cfg.cleanNameProperty] = r.cleaned_name;
  } else if (r.current.clean !== r.cleaned_name) props[cfg.cleanNameProperty] = r.cleaned_name;
  if (cfg.matchKeyProperty && r.match_key && r.current.matchKey !== r.match_key) props[cfg.matchKeyProperty] = r.match_key;
  if (!Object.keys(props).length) { skipped.push({ id: r.id, reason: 'already_current' }); continue; }
  updates.push({ id: r.id, properties: props, before: r.original_name, after: r.cleaned_name, suffixes: r.extracted_suffixes });
}

let blocked = null;
if (cfg.overwriteName && !cfg.rawNameProperty && !cfg.allowOverwriteWithoutBackup) blocked = 'overwrite_without_backup: set RAW_NAME_PROPERTY or ALLOW_OVERWRITE_WITHOUT_BACKUP=true';
const ratio = counts.scanned ? updates.filter((u) => 'name' in u.properties).length / counts.scanned : 0;
if (!blocked && cfg.overwriteName && counts.scanned >= 20 && ratio > cfg.maxChangeRatio) blocked = `circuit_breaker: ${(ratio * 100).toFixed(0)}% of scanned names would be overwritten (> MAX_CHANGE_RATIO ${cfg.maxChangeRatio})`;

const deferred = updates.length > cfg.maxUpdatesPerRun ? updates.slice(cfg.maxUpdatesPerRun).map((u) => u.id) : [];
const toWrite = blocked ? [] : updates.slice(0, cfg.maxUpdatesPerRun);
const batches = [];
for (let i = 0; i < toWrite.length; i += cfg.updateBatchSize) {
  const slice = toWrite.slice(i, i + cfg.updateBatchSize);
  batches.push({ batchNo: batches.length + 1, ids: slice.map((u) => u.id), body: { inputs: slice.map((u) => ({ id: u.id, properties: u.properties })) } });
}
return [{ json: {
  counts: { ...counts, updates: updates.length, skipped: skipped.length, deferred: deferred.length },
  updates, skipped, deferred, blocked, batches,
  writeAllowed: cfg.writeToHubspot && !blocked && batches.length > 0,
  samples: updates.filter((u) => u.before !== u.after).slice(0, cfg.notifySampleSize).map((u) => ({ id: u.id, before: u.before, after: u.after, suffixes: u.suffixes })),
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Collect Update Results
// Joins batch/update responses by index. HubSpot rejects a whole batch when
// one input is invalid (e.g. a missing custom property), so failures are
// reported per batch with the HubSpot message.
// ─────────────────────────────────────────────────────────────────────────────
const batches = $('Emit Update Batches').all();
const resp = $input.all();
if (resp.length !== batches.length) throw new Error(`Update result mismatch: ${batches.length} batches vs ${resp.length} responses. Unpin "HubSpot: Batch Update Companies" or align its items.`);
const results = batches.map((b, i) => {
  const j = resp[i].json || {};
  const failed = Boolean(j.error) || j.status === 'error';
  return { batchNo: b.json.batchNo, records: b.json.ids.length, ok: !failed, updated: Array.isArray(j.results) ? j.results.length : 0, error: failed ? String(j.error?.message || j.message || j.error || 'batch_failed').slice(0, 300) : null };
});
return [{ json: { results, updated: results.reduce((n, r) => n + r.updated, 0), failedBatches: results.filter((r) => !r.ok).length } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Notification
// Slack summary + webhook JSON: scanned, cleaned, skipped, written, failures
// and sample before → after transformations (company names only).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const cmp = $('Build Batch Updates').first().json;
const src = $('Mock HubSpot Companies').isExecuted ? $('Mock HubSpot Companies').first().json : $('Collect Search Pages').first().json;
let res = null;
try { res = $('Collect Update Results').isExecuted ? $('Collect Update Results').first().json : null; } catch (e) { res = null; }
const c = cmp.counts;
const mode = cfg.sandboxMode ? 'SANDBOX (synthetic companies, nothing written)' : cfg.writeToHubspot ? 'LIVE (written to HubSpot)' : cfg.dryRun ? 'DRY RUN (nothing written)' : 'WRITE DISABLED (nothing written)';
const target = cfg.overwriteName ? `name (original → ${cfg.rawNameProperty || 'not backed up'})` : cfg.cleanNameProperty;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'HubSpot company name standardizer', emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `*${mode}* · scope \`${src.scope}\` · target \`${target}\`` }] },
  { type: 'section', text: { type: 'mrkdwn', text: `🔎 *${c.scanned}* scanned · ✂️ *${c.suffix_removed}* suffixes removed · 🧹 ${c.whitespace_normalized} whitespace fixes · ✅ ${c.already_clean} already clean · ⏭️ *${c.skipped}* skipped · 📝 *${res ? res.updated : 0}* written${c.deferred ? ` · ${c.deferred} deferred` : ''}` } },
];
if (cmp.samples.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Samples*\n${cmp.samples.map((s) => `• \`${s.id}\` ${esc(s.before)} → *${esc(s.after)}*${s.suffixes.length ? ` _(${esc(s.suffixes.join(', '))})_` : ''}`).join('\n')}`.slice(0, 2900) } });
if (cmp.blocked) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `⛔ *Writes blocked:* ${esc(cmp.blocked)}` } });
if (res && res.failedBatches) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `❌ *${res.failedBatches} batch(es) failed:* ${res.results.filter((r) => !r.ok).map((r) => `#${r.batchNo} ${esc(r.error)}`).join('; ')}`.slice(0, 2900) } });
if (src.moreAvailable) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `More matching companies than BATCH_LIMIT (${cfg.batchLimit}); ${src.searchCapReached ? 'HubSpot search stops at 10,000 results: use SEARCH_SCOPE=backfill.' : 'the next run continues.'}` }] });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `n8n run ${cfg.runId}` }] });
const worthNotifying = c.updates > 0 || Boolean(cmp.blocked) || Boolean(res && res.failedBatches) || cfg.notifyOnEveryRun;
return [{ json: { worthNotifying,
  slackBody: { text: `Company name standardizer: ${c.scanned} scanned, ${c.suffix_removed} cleaned, ${res ? res.updated : 0} written (${mode}).`, blocks },
  webhookBody: { event: 'hubspot.company_names.standardized', runId: cfg.runId, generatedAt: new Date().toISOString(), mode: cfg.sandboxMode ? 'sandbox' : cfg.writeToHubspot ? 'live' : 'dry_run',
    scope: src.scope, target, counts: c, written: res ? res.updated : 0, failedBatches: res ? res.failedBatches : 0, blocked: cmp.blocked, samples: cmp.samples } } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path, and the only place the backfill cursor moves:
// it advances to the highest scanned company ID only after a successful
// production write run with nothing blocked, failed or deferred.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const one = (n) => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const all = (n) => { try { return $(n).isExecuted ? $(n).all().map((i) => i.json) : []; } catch (e) { return []; } };
const src = one('Mock HubSpot Companies') || one('Collect Search Pages') || {};
const cl = one('Legal Suffix Normalization & Cleaning');
const cmp = one('Build Batch Updates');
const res = one('Collect Update Results');
const sl = all('Slack: Post Summary');
const wh = all('Webhook: Post Summary');

let cursor = { scope: src.scope || cfg.searchScope, before: src.cursor || null, after: src.cursor || null, advanced: false };
if (cfg.searchScope === 'backfill' && !cfg.sandboxMode && cfg.writeToHubspot && cfg.executionMode === 'production' && cmp && !cmp.blocked && !cmp.deferred.length && !(res && res.failedBatches) && src.maxId) {
  try { const store = $getWorkflowStaticData('global'); store.backfillCursor = String(src.maxId); cursor = { ...cursor, after: String(src.maxId), advanced: true }; } catch (e) { /* static data unavailable */ }
}
let outcome = 'no_companies';
if (cl && cl.counts.scanned) {
  if (!cmp.updates.length) outcome = 'nothing_to_update';
  else if (cmp.blocked) outcome = 'writes_blocked';
  else if (cfg.sandboxMode) outcome = 'updates_found_sandbox';
  else if (!cfg.writeToHubspot) outcome = cfg.dryRun ? 'updates_found_dry_run' : 'updates_found_write_disabled';
  else if (res && res.failedBatches) outcome = res.updated ? 'updated_partially' : 'update_failed';
  else outcome = cmp.deferred.length ? 'updated_more_pending' : 'updated';
}
const status = (list) => (!list.length ? 'not_sent' : list.some((x) => x.error) ? 'failed' : 'sent');
return [{ json: {
  workflow: 'n8n-hubspot-company-legal-suffix-standardizer',
  runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, writeToHubspot: cfg.writeToHubspot, overwriteName: cfg.overwriteName },
  target: { cleanNameProperty: cfg.cleanNameProperty || null, rawNameProperty: cfg.rawNameProperty || null, matchKeyProperty: cfg.matchKeyProperty || null },
  source: { source: src.source || null, scope: src.scope || null, total: src.total ?? null, moreAvailable: Boolean(src.moreAvailable), searchCapReached: Boolean(src.searchCapReached) },
  backfillCursor: cursor,
  counts: cmp ? cmp.counts : (cl ? cl.counts : null),
  blocked: cmp ? cmp.blocked : null,
  changes: cmp ? cmp.updates.map((u) => ({ id: u.id, before: u.before, after: u.after, suffixes: u.suffixes, properties: Object.keys(u.properties) })) : [],
  skipped: cmp ? cmp.skipped : [],
  refusedStrips: cl ? cl.records.filter((r) => r.refused.length).map((r) => ({ id: r.id, name: r.original_name, refused: r.refused })) : [],
  batches: res ? res.results : [],
  notifications: { slack: status(sl), webhook: status(wh) },
} }];
